// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(1496000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.waitForLoadState('networkidle');

    // --- cycle 1: seed an item, then reset the library ---
    await page.getByTestId("toolbar-rectangle").click({ force: true });
    await page.mouse.move(400, 300);
    await page.mouse.down();
    await page.mouse.move(560, 420, { steps: 10 });
    await page.mouse.up();
    await page.getByRole("checkbox", { name: "Library" }).click({ force: true });
    await page.locator("div.library-unit__dragger").first().click();
    await expect(page.getByText("Personal Library")).toBeVisible();

    await page.getByTestId("library").getByTestId("dropdown-menu-button").click();
    await page.getByTestId("dropdown-menu").getByRole("menuitem", { name: "Reset library" }).click();
    await expect(page.getByText("This will clear your library. Are you sure?")).toBeVisible();
    await page.getByRole("button", { name: "Confirm" }).click();
    await expect(page.getByText("No items added yet...")).toBeVisible();

    // --- cycle 2: re-add a different item and reset again. The second reset runs
    // with the item-thumbnail cache already populated by cycle 1, so it exercises
    // the repeat invocation of the removeAllLibrary branch. ---
    await page.getByTestId("toolbar-ellipse").click({ force: true });
    await page.mouse.move(650, 300);
    await page.mouse.down();
    await page.mouse.move(790, 420, { steps: 10 });
    await page.mouse.up();
    await page.getByRole("checkbox", { name: "Library" }).click({ force: true });
    await page.locator("div.library-unit__dragger").first().click();
    await expect(page.getByText("Personal Library")).toBeVisible();

    await page.getByTestId("library").getByTestId("dropdown-menu-button").click();
    await page.getByTestId("dropdown-menu").getByRole("menuitem", { name: "Reset library" }).click();
    await page.getByRole("button", { name: "Confirm" }).click();

    // the repeat reset must empty the library just like the first one
    await expect(page.getByText("No items added yet...")).toBeVisible();
    await expect(page.getByTestId("library").locator("div.library-unit")).toHaveCount(0);
});
